// The Executive Frame mark, drawn inline so it can take the page's ink
// colour and draw itself on. The loop and triangle come from the brand
// pack through mark-paths.js (generated by npm run tokens); never redraw,
// close, rotate or flip the loop here.
//
// The mark has 1 meaning and 1 motion. It is still, or it draws on once
// when the app opens: the loop traces from its lower start over
// --mark-draw-on (1200ms) while the triangle fades in. It never loops,
// never pulses and is never a progress meter or a loading spinner. Under
// reduced motion the finished mark is shown at once (see app.css).

import { LOOP, STROKES, TRIANGLE } from './mark-paths.js';

const NS = 'http://www.w3.org/2000/svg';

// Returns an <svg> element. draw: true plays the draw on once.
// size is the drawn size in px and picks the pack's stroke for it:
// favicon below 24, standard from 24 to 240, display above.
export function createMark({ draw = false, label = '', size = 72 } = {}) {
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', '0 0 100 100');
  svg.setAttribute('fill', 'none');
  svg.setAttribute('class', 'mark');
  if (label) {
    svg.setAttribute('role', 'img');
    svg.setAttribute('aria-label', label);
  } else {
    svg.setAttribute('aria-hidden', 'true');
  }
  if (draw) svg.classList.add('mark-draw');

  const loop = document.createElementNS(NS, 'path');
  loop.setAttribute('d', LOOP);
  loop.setAttribute('class', 'mark-ring');
  loop.setAttribute('pathLength', '100');
  loop.setAttribute('stroke', 'currentColor');
  loop.setAttribute('stroke-width', String(size < 24 ? STROKES.favicon : size >= 240 ? STROKES.display : STROKES.standard));
  loop.setAttribute('stroke-linecap', 'round');
  loop.setAttribute('stroke-linejoin', 'round');

  const triangle = document.createElementNS(NS, 'path');
  triangle.setAttribute('d', TRIANGLE);
  triangle.setAttribute('class', 'mark-triangle');
  triangle.setAttribute('pathLength', '100');
  triangle.setAttribute('fill', 'currentColor');

  svg.append(loop, triangle);
  return svg;
}

// Replaces every <span data-mark> placeholder on the page with the mark.
// data-mark="draw" plays the draw on once.
export function mountMarks(root = document) {
  for (const el of root.querySelectorAll('[data-mark]')) {
    const svg = createMark({ draw: el.dataset.mark === 'draw', label: el.dataset.label || '', size: Number(el.dataset.px) || 72 });
    for (const cls of el.classList) svg.classList.add(cls);
    el.replaceWith(svg);
  }
}
